# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
import os

from app.extensions import db
from app.models import DailyQuest
from app.services.gamification import lb_rebuild

_FRESH_SCHEMA_STAMP = "aa11bb22cc33"


def _handle_upgrade_failure(app, message):
    db.session.rollback()
    app.logger.exception(message)
    if os.environ.get("FITX_DB_UPGRADE_FAIL_OPEN") != "1":
        raise


def init_database(app):
    # Alembic/Flask-Migrate komutları (flask db migrate/upgrade/stamp) app
    # factory'yi import eder; bu sırada create_all çalışırsa autogenerate boş
    # diff görür ve taze DB'lerde migration zinciri anlamsızlaşır. Migration
    # komutlarını çalıştırırken FITX_SKIP_DB_INIT=1 ayarla (bkz. CLAUDE.md).
    if os.environ.get("FITX_SKIP_DB_INIT") == "1":
        return
    _migrations_dir = os.path.join(app.root_path, "..", "migrations")
    with app.app_context():
        # ── Alembic zinciri (konsolsuz, kendi kendine yeten) ──
        # Bekleyen migration'lar create_all'dan ÖNCE uygulanmalı: yeni bir
        # migration tablo oluşturuyorsa create_all onu önce yaratır ve
        # op.create_table çakışırdı. Compose tek instance/tek worker çalıştırdığı
        # için boot'ta otomatik upgrade'de eşzamanlı migration yarışı yok.
        _has_alembic = False
        try:
            from sqlalchemy import inspect as sa_inspect
            _has_alembic = sa_inspect(db.engine).has_table("alembic_version")
            # Boot'ta otomatik upgrade için kapatma anahtarı (I-M1). Tek-worker
            # invariantı bozulup birden çok container/worker aynı RDS'e karşı
            # ölçeklenirse eşzamanlı boot upgrade'leri yarışabilir; o durumda
            # FITX_DB_AUTO_UPGRADE=0 ile boot upgrade'i kapat ve deploy'da
            # tek-seferlik `flask db upgrade` job'ı çalıştır. Varsayılan "1" →
            # mevcut davranış (per-boot upgrade) korunur.
            _run_upgrade = (_has_alembic and os.path.isdir(_migrations_dir)
                            and os.environ.get("FITX_DB_AUTO_UPGRADE", "1") == "1")
        except Exception:
            # Inspect hatası (örn. DB henüz erişilemez): eski davranışı koru —
            # aşağıdaki create_all zaten aynı hatayla patlar ve boot'u durdurur.
            db.session.rollback()
            _run_upgrade = False
            app.logger.exception("[DB] Şema inspect başarısız.")
        if _run_upgrade:
            try:
                from flask_migrate import upgrade
                upgrade()
            except Exception:
                # A4: migration hatası SESSİZCE yutulmaz. Eski davranış boot'u
                # sürdürüyordu → uygulama kod'un gerisinde bir şemayla trafik
                # alıyor, drift ilk 500'e kadar görünmez kalıyordu. Fail-fast:
                # boot ölür → container unhealthy → deploy health gate rollback
                # yapar. Acil kaçış: FITX_DB_UPGRADE_FAIL_OPEN=1 eski davranışı
                # (logla + devam et) geri getirir.
                _handle_upgrade_failure(
                    app,
                    "[DB] Alembic upgrade başarısız — şema migration zinciri gerisinde kalmış olabilir.",
                )

        db.create_all()

        # Fresh schemas are created from current model metadata, then stamped at
        # the last revision whose schema is represented by that metadata. Run
        # the remaining migrations before any seed/backfill helper can commit:
        # an upgrade failure must not leave durable application data in a
        # partially migrated database.
        if not _has_alembic:
            try:
                from flask_migrate import stamp, upgrade
                if os.path.isdir(_migrations_dir):
                    stamp(revision=_FRESH_SCHEMA_STAMP)
                    upgrade()
                    app.logger.info("[DB] Taze şema Alembic head'e yükseltildi.")
            except Exception:
                _handle_upgrade_failure(
                    app,
                    "[DB] Taze şemayı Alembic zincirine alma başarısız.",
                )

        # I-M1: eski ham idempotent ALTER/UPDATE döngüsü KALDIRILDI. Tüm kolonlar
        # artık ya Alembic zincirinde (drift kapatan migration f1a2b3c4d5e6 dahil)
        # ya da fresh DB'lerde yukarıdaki create_all ile geliyor; tek-seferlik veri
        # düzeltmeleri (user_quest_progress.is_claimed backfill + quest başlıklarını
        # TR'leştirme) de o migration'a taşındı. Böylece her boot'ta dönen tam-tablo
        # UPDATE'i ve şema-drift'i gizleyen ~20 ham ALTER ortadan kalktı; migration
        # zinciri artık şemanın tek doğruluk kaynağı (CI schema-drift guard bloklayıcı).

        if DailyQuest.query.count() == 0:
            for q in [
                DailyQuest(title="Günlük Giriş", description="Bugün uygulamaya giriş yap", points_reward=10, quest_type="login"),
                DailyQuest(title="Antrenman Kaydet", description="Bir antrenman planı oluştur veya kaydet", points_reward=50, quest_type="workout_logged"),
                DailyQuest(title="Bir Arkadaşına Yardım Et", description="Bir arkadaşına mesaj gönder", points_reward=30, quest_type="suggestion_sent"),
            ]:
                db.session.add(q)
            db.session.commit()
        if not DailyQuest.query.filter_by(quest_type="supplement_added").first():
            db.session.add(DailyQuest(
                title="Dolabını Güncelle",
                description="Supplement dolabına yeni bir ürün ekle",
                points_reward=25, quest_type="supplement_added"
            ))
            db.session.commit()
        if not DailyQuest.query.filter_by(quest_type="meal_logged").first():
            db.session.add(DailyQuest(
                title="Öğün Kaydet",
                description="Bugün bir öğün kaydet",
                points_reward=20, quest_type="meal_logged"
            ))
            db.session.commit()

        # Görev ekonomisini derinleştir: dönüşümlü ek görevler (su / check-in / davet).
        # Idempotent — her quest_type yalnızca bir kez eklenir.
        # NOT: meal_logged BURADA tekrar TANIMLANMAZ — yukarıdaki özel blok (first-
        # writer-wins, ödül 20) zaten ekliyor. Mükerrer 15'lik giriş hep ölü kalıyor
        # ve seeding sırası değişirse latent tutarsızlık yaratıyordu (#15).
        _extra_quests = [
            ("water_logged",     "Su Hedefi",            "Bugün su takibini güncelle",                    10),
            ("checkin_done",     "Haftalık Check-in",    "Kilonu güncelle veya check-in yap",             20),
            ("friend_invited",   "Bir Arkadaşını Davet Et", "Davet bağlantını bir arkadaşınla paylaş",    40),
        ]
        for qtype, title, desc, pts in _extra_quests:
            if not DailyQuest.query.filter_by(quest_type=qtype).first():
                db.session.add(DailyQuest(title=title, description=desc,
                                          points_reward=pts, quest_type=qtype))
        db.session.commit()

        # Meydan okuma kataloğunu tohumla (idempotent — code'a göre). Hatası boot'u
        # kırmasın; eski kod 3 yeni tabloyu yok sayabilir (additive deploy).
        try:
            from app.services.challenges import seed_challenges
            seed_challenges()
        except Exception:
            db.session.rollback()
            # Sessiz yutma DEĞİL (triage #5): kırık bir seed sinyalsiz kaybolmasın.
            app.logger.warning("[DB_INIT] seed_challenges başarısız (boot devam ediyor)",
                               exc_info=True)

        # Davet kodu olmayan mevcut kullanıcılara tek seferlik backfill.
        try:
            from app.services.referral import backfill_referral_codes
            backfill_referral_codes()
        except Exception:
            db.session.rollback()
            app.logger.warning("[DB_INIT] backfill_referral_codes başarısız (boot devam ediyor)",
                               exc_info=True)

        # Liderlik sorted set'lerini Postgres'ten doldur (Redis varsa). Redis sonradan
        # ayağa kalkarsa ilk leaderboard isteği zaten Postgres'e düşer; sonraki restart hidratlar.
        lb_rebuild()
